import {chromium} from 'playwright'
import assert from 'node:assert/strict'
import fs from 'node:fs/promises'
const base=new URL(process.env.ABIS_PREVIEW_URL||'http://127.0.0.1:5186').origin,out='./qa-output/20261113'
assert.match(await(await fetch(`${base}/src/api/index.js`)).text(),/"VITE_USE_MOCK": "true"/)
await fs.mkdir(out,{recursive:true})
const browser=await chromium.launch(),page=await browser.newPage({viewport:{width:1024,height:900},locale:'zh-CN',timezoneId:'Asia/Shanghai',reducedMotion:'reduce'})
const checks=[],errors=[],backendRequests=[]
page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});page.on('request',r=>{if(['xhr','fetch'].includes(r.resourceType())&&(new URL(r.url()).origin!==base||/\/(abis-admin|admin-api)\//.test(r.url())))backendRequests.push(r.url())})
const pass=s=>{checks.push(s);console.log('PASS',s)},button=name=>page.getByRole('button',{name,exact:true}),loaded=()=>page.waitForFunction(()=>!document.querySelector('.el-loading-mask,.el-button.is-loading'))
const app=page.getByRole('dialog',{name:'申请人详情',exact:true}),log=page.getByRole('dialog',{name:'请求详情',exact:true})
const stable=()=>page.waitForFunction(()=>{const d=document.querySelector('.applicant-drawer');return d&&Math.abs(d.getBoundingClientRect().right-innerWidth)<1})
const open=async id=>{await page.locator('.applicants-page .el-table__row').filter({hasText:id}).getByRole('button',{name:'查看详情',exact:true}).click();await loaded();await stable()}
const close=async()=>{await app.getByRole('button',{name:'关闭',exact:true}).click();await app.waitFor({state:'hidden'})}
try{
 await page.goto(`${base}/login`);await page.locator('.login-content input').nth(0).fill('admin');await page.locator('.login-content input').nth(1).fill('admin123');await button('登录').click();await page.waitForURL('**/monitor');await loaded()
 assert.equal(await page.locator('.service-card').count(),3);assert.equal(await page.locator('.storage-row').count(),4);assert.deepEqual(await page.locator('.status-overview dd').allTextContents(),['10','8','1','1']);assert.equal(await page.locator('.storage-row').last().locator('td').first().innerText(),'MinIO');assert.ok((await page.locator('.storage-section').boundingBox()).y+(await page.locator('.storage-section').boundingBox()).height<900);assert.equal(await page.locator('.has-abnormal .summary-icon').evaluate(el=>getComputedStyle(el).color),'rgb(212, 63, 71)');assert.equal(await page.locator('.has-abnormal dd').evaluate(el=>getComputedStyle(el).color),'rgb(212, 63, 71)');
 await page.screenshot({path:`${out}/monitor-1024.png`,fullPage:true});pass('1024×900 first screen shows three service cards plus all four storage rows; abnormal icon and count are red on the shared summary background')
 await page.setViewportSize({width:1200,height:1000})
 for(const width of[736,660,560,500,480]){await page.locator('.monitor-page').evaluate((el,w)=>{el.style.width=`${w}px`;el.style.maxWidth='100%'},width);await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))));const cards=await page.locator('.service-card').evaluateAll(ns=>ns.map(n=>n.getBoundingClientRect().toJSON()));if(width>660){assert.equal(cards[0].y,cards[2].y)}else if(width>500){assert.equal(cards[0].y,cards[1].y);assert.ok(cards[2].y>cards[0].y);assert.equal(cards[2].width,width);const pair=await page.locator('[data-service="algorithm-2"] .instance-row').evaluateAll(ns=>ns.map(n=>n.getBoundingClientRect().toJSON()));assert.equal(pair[0].y,pair[1].y)}else{assert.ok(cards[0].y<cards[1].y&&cards[1].y<cards[2].y);const pair=await page.locator('[data-service="algorithm-2"] .instance-row').evaluateAll(ns=>ns.map(n=>n.getBoundingClientRect().toJSON()));assert.ok(pair[0].y<pair[1].y)}assert.ok(await page.locator('.monitor-page').evaluate(el=>el.scrollWidth<=el.clientWidth+1));if([736,560,480].includes(width))await page.locator('.monitor-page').screenshot({path:`${out}/monitor-container-${width}.png`})}pass('736px container keeps three columns, 560px uses two plus a full-width algorithm card, and 480px stacks cards and instance rows without gaps')
 await page.locator('.monitor-page').evaluate(el=>{el.style.width='736px'});await button('异常').click();assert.equal(await page.locator('.storage-section').count(),0);assert.deepEqual(await page.locator('.instance-id').allTextContents(),['face-1']);assert.equal(await page.locator('.service-card').evaluate(el=>el.getBoundingClientRect().width),736);await button('未知').click();assert.equal(await page.locator('.service-card').count(),0);assert.equal(await page.locator('.storage-row').count(),1);await button('正常').click();assert.equal(await page.locator('.instance-row').count(),8);await button('全部').click();assert.equal(await page.locator('.instance-row').count(),10)
 await page.evaluate(async()=>{const api=(await import('/src/api/index.js')).default;window.health=api.getHealth;api.getHealth=async()=>{const s=await window.health();s.items=s.items.filter(g=>g.key==='system'||g.key==='algorithm-1');return s}});await button('立即刷新').click();await loaded();const two=await page.locator('.service-card').evaluateAll(ns=>ns.map(n=>n.getBoundingClientRect().toJSON()));assert.equal(two[0].y,two[1].y);assert.equal(two[0].width,two[1].width);await page.evaluate(async()=>{(await import('/src/api/index.js')).default.getHealth=window.health});await button('立即刷新').click();await loaded();pass('summary filters hide empty sections, one service card fills the container, and two cards divide the width evenly')
 await page.getByRole('menuitem',{name:'申请人列表',exact:true}).click();await loaded()
 const shared=await page.evaluate(async()=>{const api=(await import('/src/api/index.js')).default;const people=(await api.listApplicants()).items;const snapshot=(await import('/src/mock/business.js')).buildBusinessSnapshot();return{details:await Promise.all(people.map(p=>api.getApplicant(p.userId))),subjects:snapshot.subjects,logs:snapshot.logs}})
 for(const person of shared.details){const faces=person.changes.filter(c=>c.feature==='face'&&c.operation==='注册');assert.ok(faces.length>0,person.userId);assert.equal(Date.parse(person.enrolledAt),Date.parse(faces.map(c=>c.effectiveAt).sort()[0]));for(const change of person.changes){assert.deepEqual(change.requestIds,[change.requestId]);const request=shared.logs.find(r=>r.requestId===change.requestId);assert.equal(request.userId,person.userId);assert.equal(request.feature,change.feature);assert.equal(request.result,'success')}}
 for(const person of shared.subjects.filter(p=>p.records.some(r=>r.feature==='finger'))){for(const image of person.records.filter(r=>r.feature==='finger')){assert.ok(image.requestId);assert.ok(shared.logs.find(r=>r.requestId===image.requestId)?.enrollmentRecords?.some(r=>r.recordId===image.recordId)||image.requestId==='REQ-00000002')}}
 pass('every visible applicant has successful face registration history, and each seeded finger record points to a success request carrying its exact image and position')
 for(const id of['U004','U006','U010','U201','U202','U203']){await open(id);await app.getByRole('tab',{name:'入库变更记录',exact:true}).click();assert.equal(await app.getByRole('tab').count(),2);await app.locator('.enrollment-changes .el-table__row').filter({hasText:'人脸注册'}).first().getByRole('button',{name:'查看日志',exact:true}).click();await page.waitForURL('**/logs?**');await loaded();assert.equal(await page.locator('.request-table .el-table__row').count(),1);assert.equal(await page.locator('.request-table .log-id').first().innerText(),`HIST-${id}-FACE`);await page.locator('.request-table .el-table__row').click();await log.waitFor();await log.getByRole('tab',{name:'接口报文',exact:true}).click();assert.equal(JSON.parse(await log.getByLabel('ABIS 请求 JSON').innerText()).userId,id);assert.match(await log.locator('.request-summary').innerText(),/人脸注册/);await log.getByRole('button',{name:'关闭',exact:true}).click();await log.waitFor({state:'hidden'});await page.goBack();await loaded();await app.waitFor();assert.equal(await app.getByRole('tab',{name:'入库变更记录',exact:true}).getAttribute('aria-selected'),'true');await close()}pass('all six seeded face applicants open exactly one historical registration log with matching user, request and modality and restore the changes tab on return')
 await page.getByRole('menuitem',{name:'日志查询',exact:true}).click();await loaded();await button('重置').click();await loaded();assert.equal(await page.locator('.request-table .el-table__row').count(),15);const headers=await page.locator('.request-table th').allTextContents();assert.equal(headers[headers.indexOf('接收时间')+1],'请求来源 IP');const sourceIndex=headers.indexOf('请求来源 IP');for(const[id,ip]of[['REQ-00000001','203.0.113.40'],['REQ-00000013','198.51.100.23'],['REQ-00000008','—']])assert.equal(await page.locator('.request-table .el-table__row').filter({hasText:id}).locator('td').nth(sourceIndex).innerText(),ip);await page.screenshot({path:`${out}/source-ip.png`,fullPage:true});const csv=await page.evaluate(async()=>(await(await import('/src/api/index.js')).default.exportLogs()).text());assert.equal(csv.trim().split(/\r?\n/).length,16);assert.match(csv,/请求来源 IP/);assert.match(csv,/198\.51\.100\.23/);assert.match(csv,/203\.0\.113\.40/);pass('default list and CSV remain fifteen requests with original async and sync source IPs and a missing-IP placeholder')
 const history=await page.evaluate(async()=>{const api=(await import('/src/api/index.js')).default;return{user:await api.listLogs({userId:'U006'}),request:await api.listLogs({requestId:'HIST-U006-FACE'}),wrong:await api.listLogs({userId:'U004',requestId:'HIST-U006-FACE'}),csv:await(await api.exportLogs({requestId:'HIST-U006-FACE'})).text()}});assert.equal(history.user.total,2);assert.equal(history.request.total,1);assert.equal(history.wrong.total,0);assert.equal(history.csv.trim().split(/\r?\n/).length,2);assert.ok(Date.parse(history.request.items[0].receivedAt)<Date.parse(history.user.items[0].receivedAt));pass('hidden historical requests are queryable and exportable by full user/request IDs while combined filters intersect')
 await page.getByRole('menuitem',{name:'申请人列表',exact:true}).click();await loaded();await button('重采样例').click();await button('三人重采结果').click();await loaded();await open('U301');await app.getByRole('tab',{name:'入库变更记录',exact:true}).click();await app.locator('.enrollment-changes .el-table__row').nth(1).getByRole('button',{name:'查看日志',exact:true}).click();await page.waitForURL('**/logs?**');await loaded();assert.deepEqual(await page.locator('.request-table .el-table__row td:first-child .log-id').allTextContents(),['RECAP-U301-005']);await page.getByPlaceholder('输入完整业务请求 ID').fill('');await button('查询').click();await loaded();assert.ok((await page.locator('.request-table .el-table__row td:first-child .log-id').allTextContents()).includes('RECAP-U301-006'));await page.goBack();await loaded();await app.waitFor();await page.screenshot({path:`${out}/u301-single-request.png`});await close();await button('恢复默认数据').click();await loaded();pass('U301 face registration opens only the 14:05 request and the 14:06 identification remains available through the user query')
 await button('监控').click();await page.getByRole('menuitem',{name:'主机资源',exact:true}).click();await page.waitForURL('**/host-resources');await loaded();assert.equal(await page.locator('.host-resources .el-table__row').count(),8);for(const width of[390,320]){await page.setViewportSize({width,height:900});await button('监控').click();await page.getByRole('menuitem',{name:'服务状态',exact:true}).click();await page.waitForURL('**/monitor');await loaded();assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));assert.equal(await page.locator('.instance-row').count(),10);assert.ok(await page.locator('.storage-row').evaluateAll(ns=>ns.every(el=>el.scrollWidth<=el.clientWidth+1)));if(width===390)await page.screenshot({path:`${out}/monitor-mobile.png`,fullPage:true})}pass('host resources preserve eight rows and the service/storage layout remains readable at 320px and 390px')
 assert.deepEqual(errors,[]);assert.deepEqual(backendRequests,[]);pass('zero browser errors and zero real-backend requests');await fs.writeFile(`${out}/report.json`,JSON.stringify({checks,errors,backendRequests},null,2));console.log(`COMPLETE ${checks.length} checks`)
}catch(e){await page.screenshot({path:`${out}/failure.png`});console.error(e);process.exitCode=1}finally{await browser.close()}
